// CommitTagPrefix is prepended to a commit sha to form the image tag CI
// publishes. Kept in one place: if the pipeline's tagging scheme ever differs,
// this is the only line that changes.
const CommitTagPrefix = "sha-"

// DefaultWatchPollInterval is how often the registry is re-asked while
// watching for a commit's images.
const DefaultWatchPollInterval = 2 * time.Second

// watchProgressInterval is how often a "still waiting" line is printed while
// watching, so a long CI build does not look like a hang. One line per poll
// would flood the terminal on a slow build.
const watchProgressInterval = 30 * time.Second

// CommitTag returns the registry tag for a commit.
func CommitTag(commit string) string { return CommitTagPrefix + commit }

// Pin is one image repository resolved to an immutable digest.
type Pin struct {
	// Image is the bare repository, as declared in component.yaml.
	Image string

	// Digest is the manifest digest, in sha256:… form.
	Digest string

	// Tag is the tag the digest was resolved from, kept for messages.
	Tag string
}

// Ref renders the pinned reference in the form kustomize writes.
func (p Pin) Ref() string { return p.Image + "@" + p.Digest }

// Resolver resolves an image reference to a descriptor. It is the seam that
// lets digest resolution be tested against an in-memory registry.
type Resolver interface {
	Resolve(ctx context.Context, ref string) (registry.Descriptor, error)
}

// NewResolver builds the production resolver. Replaced in tests via this
// package-level variable.
var NewResolver = func(userAgent string) (Resolver, error) {
	return registry.NewClient(registry.WithUserAgent(userAgent))
}

// ResolveDigests resolves every image in the component to the digest CI
// published for commit.
//
// The digest comes from whatever the registry actually returns for the tag,
// which is the point of resolving rather than constructing a reference: for a
// multi-architecture build the tag points at an image index, and the index
// digest is what must be pinned. Registries have also been known to convert
// between Docker and OCI manifest types on read, changing the digest, so the
// only safe value is the one this lookup observed.
func ResolveDigests(ctx context.Context, r Resolver, comp *gitops.ComponentConfig, commit string) ([]Pin, error) {
	tag := CommitTag(commit)

	pins := make([]Pin, 0, len(comp.Images))
	for _, img := range comp.Images {
		ref := img.Name + ":" + tag
		desc, err := r.Resolve(ctx, ref)
		if err != nil {
			return nil, resolveError(err, img.Name, tag)
		}
		if desc.Digest == "" {
			return nil, fmt.Errorf("registry returned no digest for %s", ref)
		}
		pins = append(pins, Pin{Image: img.Name, Digest: desc.Digest, Tag: tag})

// ReleasesRepo returns the repository holding a component's releases, given
// any one of its image repositories.
func ReleasesRepo(image string) string {
	return strings.TrimSuffix(image, "/") + ReleasesRepoSuffix
}

// Ref builds the reference for one version of a component's releases.
func Ref(releasesRepo, version string) string {
	return releasesRepo + ":" + version
}

// Registry is the registry surface a release needs. It is an interface so the
// commands can be tested against an in-memory registry, and so callers never
// import internal/registry directly.
type Registry interface {
	PushArtifact(ctx context.Context, ref string, art registry.Artifact) (registry.Descriptor, error)
	PullArtifact(ctx context.Context, ref string) (registry.Artifact, registry.Descriptor, error)
	Resolve(ctx context.Context, ref string) (registry.Descriptor, error)
	ListTags(ctx context.Context, ref string) ([]string, error)
}

// NewRegistry builds the production registry client. Replaced in tests via
// this package-level variable.
var NewRegistry = func(userAgent string) (Registry, error) {
	return registry.NewClient(registry.WithUserAgent(userAgent))
}

// Push publishes a manifest at ref and returns its digest.
func Push(ctx context.Context, reg Registry, ref string, m *Manifest) (string, error) {
	body, err := json.MarshalIndent(m, "", "  ")
	if err != nil {
		return "", fmt.Errorf("encode release manifest: %w", err)
	}
	body = append(body, '\n')

	desc, err := reg.PushArtifact(ctx, ref, registry.Artifact{
		ArtifactType: ArtifactType,
		Layers:       []registry.Blob{{MediaType: MediaTypeJSON, Data: body}},
		Annotations: map[string]string{
			AnnotationComponent:   m.Component,
			AnnotationCommit:      m.Source.Commit,
			annotationTitle:       m.Component,
			annotationVersion:     m.Version,
			annotationCreated:     m.CreatedAt.UTC().Format(createdLayout),
			annotationRevision:    m.Source.Commit,
			annotationDescription: firstLine(m.Notes),
		},
	})
	if err != nil {
		return "", fmt.Errorf("push release %s: %w", ref, err)
	}
	return desc.Digest, nil
}

// Pull reads and validates the manifest at ref.
func Pull(ctx context.Context, reg Registry, ref string) (*Manifest, error) {
	art, _, err := reg.PullArtifact(ctx, ref)
	if err != nil {
		return nil, err
	}
	if art.ArtifactType != ArtifactType {
		return nil, fmt.Errorf("%w: %s has artifact type %q, want %q", ErrNotRelease, ref, art.ArtifactType, ArtifactType)
	}
	if len(art.Layers) != 1 {
		return nil, fmt.Errorf("%w: %s has %d layers, want exactly 1", ErrNotRelease, ref, len(art.Layers))
	}
	if art.Layers[0].MediaType != MediaTypeJSON {
		return nil, fmt.Errorf("%w: %s layer has media type %q, want %q", ErrNotRelease, ref, art.Layers[0].MediaType, MediaTypeJSON)
	}

	var m Manifest
	if err := json.Unmarshal(art.Layers[0].Data, &m); err != nil {
		return nil, fmt.Errorf("%w: %s: %v", ErrNotRelease, ref, err)
	}
	if err := m.Validate(); err != nil {
		return nil, fmt.Errorf("%s: %w", ref, err)
	}
	return &m, nil
}

