func TestSplitChannel(t *testing.T) {
	cases := []struct {
		in     string
		pubsub string
		topic  string
		wantOk bool
	}{
		{"product-pubsub/product-topic", "product-pubsub", "product-topic", true},
		{"product-pubsub/deep/with/slashes", "product-pubsub", "deep/with/slashes", true},
		{"no-slash", "", "", false},
		{"/empty-pubsub", "", "", false},
		{"empty-topic/", "", "", false},
		{"", "", "", false},
	}
	for _, tc := range cases {
		pubsub, topic, err := SplitChannel(tc.in)
		if gotOk := err == nil; gotOk != tc.wantOk {
			t.Errorf("SplitChannel(%q) ok = %v, want %v (err %v)", tc.in, gotOk, tc.wantOk, err)
			continue
		}
		if tc.wantOk && (pubsub != tc.pubsub || topic != tc.topic) {
			t.Errorf("SplitChannel(%q) = %q, %q, want %q, %q", tc.in, pubsub, topic, tc.pubsub, tc.topic)
		}
	}
}

// Two groups carrying the same message id: a bare reference names both, so
// resolving it is refused rather than guessed.
func TestResolveBareRefAmbiguousAcrossGroups(t *testing.T) {
	doc := &Export{
		MessageGroups: map[string]MessageGroup{
			"one": {ID: "one", Messages: map[string]Message{"shared.event": {ID: "shared.event"}}},
			"two": {ID: "two", Messages: map[string]Message{"shared.event": {ID: "shared.event"}}},
		},
	}
	_, err := ResolveMessage(doc, "shared.event")
	if err == nil || !strings.Contains(err.Error(), "/messagegroups/one") || !strings.Contains(err.Error(), "/messagegroups/two") {
		t.Errorf("err = %v, want ambiguity naming both groups", err)
	}
}

func TestResolveListOfExportDegradesToEmptyMaps(t *testing.T) {
	// An export with no collections at all is a valid empty registry.
	doc := &Export{}
	_, err := ResolveMessage(doc, "anything")
	var notFound *MessageNotFoundError
	if !errors.As(err, &notFound) {
		t.Errorf("err = %v, want MessageNotFoundError on the empty registry", err)
	}
}

func TestResolveChannelsAreSorted(t *testing.T) {
	doc := &Export{
		MessageGroups: map[string]MessageGroup{
			"g": {ID: "g", Messages: map[string]Message{"m": {ID: "m", Versions: map[string]*MessageVersion{
				"1": {VersionID: "1", IsDefault: true},
			}}}},
		},
		Endpoints: map[string]Endpoint{
			"b": {ID: "b", Usage: []string{"producer"}, Channel: "z-pubsub/z-topic", MessageGroups: []string{"/messagegroups/g"}},
			"a": {ID: "a", Usage: []string{"producer"}, Channel: "a-pubsub/a-topic", MessageGroups: []string{"/messagegroups/g"}},
		},
	}
	res, err := ResolveMessage(doc, "m")
	if err != nil {
		t.Fatal(err)
	}
	if len(res.Channels) != 2 || res.Channels[0].Pubsub != "a-pubsub" {
		t.Errorf("channels = %+v, want sorted by pubsub", res.Channels)
	}
}

func TestSchemaDefaultVersionPinnedFromDocView(t *testing.T) {
	doc := &Export{
		MessageGroups: map[string]MessageGroup{
			"g": {ID: "g", Messages: map[string]Message{"m": {ID: "m", Versions: map[string]*MessageVersion{
				"1": {VersionID: "1", IsDefault: true, DataSchemaXID: "/schemagroups/sg/schemas/s"},
			}}}},
		},
		SchemaGroups: map[string]SchemaGroup{
			"sg": {ID: "sg", Schemas: map[string]Schema{
				"s": {ID: "s", Versions: map[string]Version{
					"3": {VersionID: "3", XID: "/schemagroups/sg/schemas/s/versions/3", IsDefault: true},
					"2": {VersionID: "2", XID: "/schemagroups/sg/schemas/s/versions/2"},
				}},
			}},
		},
	}
	res, err := ResolveMessage(doc, "m")
	if err != nil {
		t.Fatal(err)
	}
	if res.DataSchemaURL != "/schemagroups/sg/schemas/s/versions/3" {
		t.Errorf("DataSchemaURL = %q, want the default version's xid", res.DataSchemaURL)
	}
}

package xregistry

import (
	"fmt"
	"strings"
)

// The typed resolution failures. Each names the entity it failed on so the
// command layer can map them to the CLI error voice — front-loaded
// failure, remediation on the second line — without re-parsing strings.

// MessageNotFoundError reports a reference that matched no message.
type MessageNotFoundError struct{ Ref string }

func (e *MessageNotFoundError) Error() string {
	return fmt.Sprintf("message %q not found in the registry", e.Ref)
}

// NoProducerError reports a message group carried by no producer endpoint.
type NoProducerError struct{ Group string }

func (e *NoProducerError) Error() string {
	return fmt.Sprintf("message group %q has no producer endpoint in the registry", e.Group)
}

// AmbiguousProducerError reports several producer endpoints carrying the
// message's group on different channels. Candidates names both channels so
// an interactive run can offer the pick list a --no-input run refuses to
// choose from.
type AmbiguousProducerError struct {
	Ref      string
	Channels []Channel
}

func (e *AmbiguousProducerError) Error() string {
	var parts []string
	for _, c := range e.Channels {
		parts = append(parts, c.Pubsub+"/"+c.Topic)
	}
	return fmt.Sprintf("message %q is produced on %d channels: %s", e.Ref, len(e.Channels), strings.Join(parts, ", "))
}

// ChannelFormatError reports a channel the <pubsub>/<topic> split rejects;
// the channel format belongs to the registry's conformance suite, and a
// half-parsed channel must not become wiring.
type ChannelFormatError struct {
	Endpoint string
	Channel  string
	err      error
}

func (e *ChannelFormatError) Error() string {
	return fmt.Sprintf("endpoint %s: %v", e.Endpoint, e.err)
}

func (e *ChannelFormatError) Unwrap() error { return e.err }

// SchemaNotFoundError reports a message's dataschemaxid that resolves to no
// schema default version in the export.
type SchemaNotFoundError struct{ XID string }

func (e *SchemaNotFoundError) Error() string {
	return fmt.Sprintf("schema %q not found in the registry", e.XID)
}

// NoDefaultVersionError reports a message whose definition carries no
// attributes on any version — a registry document the client does not
// understand, not a wiring the CLI can guess.
type NoDefaultVersionError struct {
	Ref   string
	Group string
}

func (e *NoDefaultVersionError) Error() string {
	return fmt.Sprintf("message %q in group %q carries no definition attributes", e.Ref, e.Group)
}

